            render_power = 2,
            color        = 0xff000000,
        },

        blur = {
            enabled   = true,
            size      = 2,
            passes    = 1,
            vibrancy  = 0.0696,
        },
    },

    animations = {
        enabled = true,
    },
    
})

-- Smooth & responsive
hl.curve("smooth", {
    type = "bezier",
    points = {
        { 0.22, 1.00 },
        { 0.36, 1.00 },
    }
})

-- Fast start, soft stop
hl.curve("smoothOut", {
    type = "bezier",
    points = {
        { 0.16, 1.00 },
        { 0.30, 1.00 },
    }
})

-- Very fast UI interaction
hl.curve("quick", {
    type = "bezier",
    points = {
        { 0.25, 0.00 },
        { 0.35, 1.00 },
    }
})

-- Slight overshoot, gives a premium feel
hl.curve("pop", {
    type = "bezier",
    points = {
        { 0.20, 0.90 },
        { 0.25, 1.08 },
    }
})

